args.content:
#!/usr/bin/env python3
"""Shift all dates in hashcards.db back by N days."""
import sqlite3, sys
from datetime import datetime, timedelta

db_path, days = sys.argv[1], int(sys.argv[2])
con = sqlite3.connect(db_path)
cur = con.cursor()

def shift_ts(ts):
    return (datetime.strptime(ts, "%Y-%m-%dT%H:%M:%S.%f") - timedelta(days=days)).strftime("%Y-%m-%dT%H:%M:%S.%f")

def shift_date(d):
    return (datetime.strptime(d, "%Y-%m-%d") - timedelta(days=days)).strftime("%Y-%m-%d")

for table, cols in [("cards", ["added_at", "last_reviewed_at", "due_date"]),
                    ("sessions", ["started_at", "ended_at"]),
                    ("reviews", ["reviewed_at", "due_date"])]:
    for col in cols:
        fn = shift_date if col == "due_date" else shift_ts
        rows = cur.execute(f"select rowid, {col} from {table} where {col} is not null").fetchall()
        for rid, val in rows:
            cur.execute(f"update {table} set {col} = ? where rowid = ?", (fn(val), rid))
con.commit()
print(f"shifted back {days} days")

